snippet_css:
:root{
  --bg: #F4F1EA;
  --fg: #22201C;
  --muted: #5A5A52;
  --surface: #FFFFFF;
  --border: #D9D1C0;
  --accent: #1F2A44;
  --accent-fg: #FFFFFF;
  --radius: 2px;
  --radius-sm: 2px;
  --shadow: 0 1px 0 rgba(184,155,94,.45);
  --btn-shadow: none;
  --art-bg: linear-gradient(180deg,#FBF9F4,#E6E0D4);
  --media-bg: linear-gradient(180deg,#E6E0D4,#D9D1C0);
  --cta-bg: #1F2A44;
  --input-bg: #FFFFFF;
  --ok: #2C6B4F;
  --warn: #8C2F2F;
  --font-display: Cinzel,'Noto Serif TC',serif;
  --font-body: 'EB Garamond','Noto Serif TC',serif;
  --font-mono: Cinzel,ui-monospace,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
